def binary_search(a, target):
    left, right = 0, len(a) - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] == target:
            result = mid
            right = mid - 1  # Continue searching on the left side
        elif a[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return result
